export type DirectRfpPortalParserStatus = "ready_to_parse" | "needs_parser" | "catalog_only";

export interface DirectRfpPortal {
  id: string;
  name: string;
  jurisdiction: string;
  state?: string;
  country: string;
  level: DirectRfpPortalLevel;
  url: string;
  searchUrl?: string;
  domain: string;
  accessMode: DirectRfpPortalAccessMode;
  requiresKey: boolean;
  requiresLogin: boolean;
  tier: 1 | 2 | 3;
  parserStatus: DirectRfpPortalParserStatus;
  notes: string;
}

