export const OFFICIAL_DIRECT_RFP_DOMAINS = new Set(DIRECT_RFP_PORTALS.map((portal) => portal.domain));

export function directRfpPortalsForSearch(includeTier3 = false): DirectRfpPortal[] {
  return DIRECT_RFP_PORTALS.filter((portal) => portal.level !== "federal" && (includeTier3 || portal.tier !== 3));
}

export function directRfpPortalByDomain(hostname: string): DirectRfpPortal | undefined {
  const normalized = hostname.toLowerCase().replace(/^www\./, "");
  return DIRECT_RFP_PORTALS.find((portal) => normalized.includes(portal.domain.toLowerCase().replace(/^www\./, "")));
}
